public AuthDto.RegisterResponse register(AuthDto.RegisterRequest request) {
        String email = request.getEmail().trim().toLowerCase();
        Optional<Account> existingOpt = accountRepository.findByEmailForUpdate(email);

        Account account;
        if (existingOpt.isPresent()) {
            Account existing = existingOpt.get();
            if (Boolean.TRUE.equals(existing.getEmailVerified())) {
                throw BusinessException.badRequest(ErrorCode.VALIDATION_FAILED, "Địa chỉ email này đã được sử dụng");
            }
            if (existing.getRole() != Role.CUSTOMER || !Boolean.TRUE.equals(existing.getActive())) {
                throw BusinessException.forbidden(ErrorCode.ACCESS_DENIED, "Tài khoản không thể đăng ký lại qua biểu mẫu công khai");
            }
            // Pending customers can retry after SMTP recovery.
            existing.setPasswordHash(passwordEncoder.encode(request.getPassword()));
            if (request.getFullName() != null && !request.getFullName().isBlank()) {
                existing.setFullName(request.getFullName().trim());
            }
            if (request.getPhone() != null && !request.getPhone().isBlank()) {
                existing.setPhone(request.getPhone().trim());
            }
            account = accountRepository.save(existing);
        } else {
            account = Account.builder()
                    .email(email)
                    .passwordHash(passwordEncoder.encode(request.getPassword()))
                    .fullName(request.getFullName() != null ? request.getFullName().trim() : null)
                    .phone(request.getPhone() != null ? request.getPhone().trim() : null)
                    .role(Role.CUSTOMER) // Khách đăng ký công khai bắt buộc là CUSTOMER
                    .active(true)
                    .emailVerified(false) // Chưa xác thực email
                    .tokenVersion(1L)
                    .createdAt(Instant.now())
                    .build();
            account = accountRepository.save(account);
        }

        // Sinh mã OTP 6 số bảo vệ HMAC-SHA256, hạn 10 phút
        OtpService.GeneratedOtp generated = otpService.generateAndSaveOtp(
                email, EmailVerificationOtp.PURPOSE_REGISTER, 10);

        // Gửi email thật qua SMTP
        mailService.sendRegistrationOtpEmail(email, account.getFullName(), generated.rawOtp(), 10);

        return AuthDto.RegisterResponse.builder()
                .email(email)
                .maskedEmail(MailService.maskEmail(email))
                .message("Tài khoản đang chờ kích hoạt. Mã xác thực 6 chữ số đã được gửi tới email của bạn. Vui lòng nhập mã để kích hoạt tài khoản.")
                .emailVerified(false)
                .cooldownSeconds(60)
                .build();
    }

public String verifyEmail(AuthDto.VerifyEmailRequest request) {
        String email = request.getEmail().trim().toLowerCase();
        Account account = accountRepository.findByEmail(email)
                .orElseThrow(() -> BusinessException.notFound(ErrorCode.VALIDATION_FAILED, "Không tìm thấy tài khoản với email này"));

        if (Boolean.TRUE.equals(account.getEmailVerified())) {
            return "Tài khoản của bạn đã được xác thực trước đó. Bạn có thể đăng nhập ngay.";
        }

        // Xác thực mã OTP (kiểm tra hạn dùng, băm HMAC, số lần thử)
        otpService.verifyOtp(email, EmailVerificationOtp.PURPOSE_REGISTER, request.getOtp());

        // Cập nhật trạng thái xác thực email
        // LƯU Ý: Không tự mở khóa nếu tài khoản đang bị admin khóa (active = false)
        account.setEmailVerified(true);
        accountRepository.save(account);

        return "Xác thực email thành công! Bạn có thể đăng nhập vào hệ thống ngay bây giờ.";
    }

public String resendRegisterOtp(String email) {
        String cleanEmail = email.trim().toLowerCase();
        Account account = accountRepository.findByEmailForUpdate(cleanEmail)
                .orElseThrow(() -> BusinessException.notFound(ErrorCode.VALIDATION_FAILED, "Địa chỉ email chưa được đăng ký trong hệ thống"));

        if (Boolean.TRUE.equals(account.getEmailVerified())) {
            throw BusinessException.badRequest(ErrorCode.VALIDATION_FAILED, "Tài khoản đã được xác thực. Bạn có thể đăng nhập ngay.");
        }

        OtpService.GeneratedOtp generated = otpService.generateAndSaveOtp(
                cleanEmail, EmailVerificationOtp.PURPOSE_REGISTER, 10);

        mailService.sendRegistrationOtpEmail(cleanEmail, account.getFullName(), generated.rawOtp(), 10);

        return "Mã xác thực mới đã được gửi tới email " + MailService.maskEmail(cleanEmail) + ". Vui lòng kiểm tra hộp thư.";
    }

public AuthDto.AuthResponse login(AuthDto.LoginRequest request) {
        String email = request.getEmail().trim().toLowerCase();
        Account account = accountRepository.findByEmail(email)
                .orElseThrow(() -> BusinessException.unauthorized(
                        ErrorCode.AUTH_INVALID_CREDENTIALS, "Tài khoản hoặc mật khẩu không đúng"));

        // 1. Kiểm tra tài khoản bị admin khóa
        if (!Boolean.TRUE.equals(account.getActive())) {
            throw BusinessException.forbidden(
                    ErrorCode.ACCESS_DENIED, "Tài khoản đã bị tạm khóa. Vui lòng liên hệ ban quản trị.");
        }

        // 2. Kiểm tra mật khẩu
        if (!passwordEncoder.matches(request.getPassword(), account.getPasswordHash())) {
            throw BusinessException.unauthorized(
                    ErrorCode.AUTH_INVALID_CREDENTIALS, "Tài khoản hoặc mật khẩu không đúng");
        }

        // 3. Kiểm tra xác thực email (Tách biệt khỏi trạng thái khóa)
        if (!Boolean.TRUE.equals(account.getEmailVerified())) {
            throw BusinessException.unauthorized(
                    ErrorCode.AUTH_EMAIL_NOT_VERIFIED,
                    "Địa chỉ email chưa được xác thực. Vui lòng xác thực email để kích hoạt tài khoản trước khi đăng nhập.");
        }

        String token = jwtService.generateToken(account);
        return AuthDto.AuthResponse.builder()
                .token(token)
                .user(AuthDto.UserInfo.builder()
                        .id(account.getId())
                        .email(account.getEmail())
                        .fullName(account.getFullName())
                        .phone(account.getPhone())
                        .role(account.getRole())
                        .build())
                .build();
    }

public void logout(Long accountId) {
        if (accountId != null) {
            accountRepository.findById(accountId).ifPresent(account -> {
                // Tăng tokenVersion để vô hiệu hóa mọi token cũ
                account.setTokenVersion(account.getTokenVersion() + 1);
                accountRepository.save(account);
            });
        }
    }

public String requestPasswordReset(AuthDto.PasswordResetRequest request) {
        String email = request.getEmail().trim().toLowerCase();
        String genericMessage = "Nếu địa chỉ email tồn tại trên hệ thống, mã xác thực khôi phục mật khẩu đã được gửi đến hộp thư của bạn.";

        Optional<Account> accountOpt = accountRepository.findByEmail(email);
        if (accountOpt.isEmpty()) {
            log.info("Yêu cầu reset mật khẩu cho email không tồn tại: {}", MailService.maskEmail(email));
            return genericMessage;
        }

        Account account = accountOpt.get();
        if (!Boolean.TRUE.equals(account.getActive())) {
            log.warn("Yêu cầu reset mật khẩu cho tài khoản đang bị khóa: {}", MailService.maskEmail(email));
            return genericMessage;
        }

        // Sinh mã OTP 6 số mục đích PASSWORD_RESET, thời hạn 15 phút
        OtpService.GeneratedOtp generated = otpService.generateAndSaveOtp(
                email, EmailVerificationOtp.PURPOSE_PASSWORD_RESET, 15);

        // Gửi email thật
        mailService.sendPasswordResetOtpEmail(email, account.getFullName(), generated.rawOtp(), 15);

        return genericMessage;
    }

public String verifyPasswordResetOtp(String rawEmail, String otp) {
        if (rawEmail == null || rawEmail.isBlank()) {
            throw BusinessException.badRequest(ErrorCode.VALIDATION_FAILED, "Email không được để trống");
        }
        String cleanEmail = rawEmail.trim().toLowerCase();
        Account account = accountRepository.findByEmail(cleanEmail)
                .orElseThrow(() -> BusinessException.badRequest(
                        ErrorCode.AUTH_INVALID_CREDENTIALS, "Tài khoản hoặc mã xác thực không hợp lệ"));

        if (!Boolean.TRUE.equals(account.getActive())) {
            throw BusinessException.badRequest(ErrorCode.ACCESS_DENIED, "Tài khoản đang bị tạm khóa.");
        }

        // 1. Xác thực mã OTP 6 số với purpose PASSWORD_RESET
        otpService.verifyOtp(cleanEmail, EmailVerificationOtp.PURPOSE_PASSWORD_RESET, otp);

        // 2. Sinh resetToken ngẫu nhiên an toàn, lưu hash vào TokenKhoiPhuc
        String rawToken = UUID.randomUUID().toString();
        String tokenHash = guestAccessService.hashToken(rawToken);

        PasswordResetToken resetTokenEntity = PasswordResetToken.builder()
                .account(account)
                .tokenHash(tokenHash)
                .expiresAt(Instant.now().plus(15, ChronoUnit.MINUTES))
                .build();

        passwordResetTokenRepository.save(resetTokenEntity);
        log.info("Xác thực OTP đặt lại mật khẩu thành công cho tài khoản: {}", MailService.maskEmail(cleanEmail));

        return rawToken;
    }

public void confirmPasswordReset(AuthDto.PasswordResetConfirmRequest request) {
        String tokenOrCode = request.getEffectiveToken();
        if (tokenOrCode.isBlank()) {
            throw BusinessException.badRequest(ErrorCode.VALIDATION_FAILED, "Mã xác thực không được để trống");
        }

        Account account = null;

        // Trường hợp 1: Sử dụng mã OTP 6 chữ số kèm email
        if (request.getEmail() != null && !request.getEmail().isBlank() && tokenOrCode.matches("^\\d{6}$")) {
            String email = request.getEmail().trim().toLowerCase();
            account = accountRepository.findByEmail(email)
                    .orElseThrow(() -> BusinessException.badRequest(
                            ErrorCode.AUTH_INVALID_CREDENTIALS, "Tài khoản hoặc mã xác thực không hợp lệ"));

            otpService.verifyOtp(email, EmailVerificationOtp.PURPOSE_PASSWORD_RESET, tokenOrCode);
        }
        // Trường hợp 2: Tra cứu token UUID trong TokenKhoiPhuc (nếu có dùng link)
        else {
            String tokenHash = guestAccessService.hashToken(tokenOrCode);
            Optional<PasswordResetToken> resetTokenOpt = passwordResetTokenRepository.findByTokenHash(tokenHash);

            if (resetTokenOpt.isPresent()) {
                PasswordResetToken resetToken = resetTokenOpt.get();
                if (resetToken.getUsedAt() != null || resetToken.getExpiresAt().isBefore(Instant.now())) {
                    throw BusinessException.badRequest(ErrorCode.AUTH_TOKEN_EXPIRED, "Mã khôi phục đã hết hạn hoặc đã sử dụng");
                }
                account = resetToken.getAccount();
                resetToken.setUsedAt(Instant.now());
                passwordResetTokenRepository.save(resetToken);
            } else if (request.getEmail() != null && !request.getEmail().isBlank()) {
                // Thử xác thực qua OTP service nếu mã gửi dạng OTP
                String email = request.getEmail().trim().toLowerCase();
                account = accountRepository.findByEmail(email)
                        .orElseThrow(() -> BusinessException.badRequest(
                                ErrorCode.AUTH_INVALID_CREDENTIALS, "Tài khoản hoặc mã xác thực không hợp lệ"));
                otpService.verifyOtp(email, EmailVerificationOtp.PURPOSE_PASSWORD_RESET, tokenOrCode);
            } else {
                throw BusinessException.badRequest(ErrorCode.AUTH_INVALID_CREDENTIALS, "Mã khôi phục không hợp lệ hoặc đã hết hạn");
            }
        }

        if (account == null) {
            throw BusinessException.badRequest(ErrorCode.AUTH_INVALID_CREDENTIALS, "Không thể xác định tài khoản cần đặt lại mật khẩu");
        }

        // Cập nhật mật khẩu băm mới
        account.setPasswordHash(passwordEncoder.encode(request.getNewPassword()));

        // Tăng tokenVersion để vô hiệu hóa toàn bộ session/JWT cũ
        account.setTokenVersion(account.getTokenVersion() + 1);

        // Lưu tài khoản (Lưu ý: Không tự ý mở khóa active nếu tài khoản bị khóa)
        accountRepository.save(account);
        log.info("Đặt lại mật khẩu thành công cho tài khoản: {}", MailService.maskEmail(account.getEmail()));
    }

public CatalogPage search(String term, Long category, Long shop, BigDecimal min, BigDecimal max, String sort, int page, int size) {
        if (page < 0 || page > 100000 || size < 1 || size > 100
                || (min != null && min.signum() < 0)
                || (max != null && max.signum() < 0)
                || (min != null && max != null && min.compareTo(max) > 0)
                || term != null && term.length() > 120) {
            throw BusinessException.badRequest(ErrorCode.VALIDATION_FAILED, "Bộ lọc hoặc phân trang không hợp lệ");
        }

        String normalizedTerm = Product.normalizeSearch(term == null ? "" : term);
        List<Product> matched = products.findAllByActiveTrue().stream()
                .filter(p -> p.getCategory() != null && Boolean.TRUE.equals(p.getCategory().getActive()))
                .filter(p -> p.getShop() == null || p.getShop().isActive())
                .filter(p -> !hasText(normalizedTerm)
                        || Product.normalizeSearch(p.getName()).contains(normalizedTerm)
                        || Product.normalizeSearch(p.getCategory().getName()).contains(normalizedTerm))
                .filter(p -> category == null || Objects.equals(p.getCategory().getId(), category))
                .filter(p -> shop == null || (p.getShop() != null && Objects.equals(p.getShop().getId(), shop)))
                .toList();

        // Checkout resolves a menu variant to a branch later. Do not show the same
        // variant once per branch/category, or collapse distinct sizes into one SKU.
        Map<String, Product> unique = new LinkedHashMap<>();
        matched.stream().sorted(Comparator
                .comparingInt((Product p) -> p.getShop() == null ? 0 : 1)
                .thenComparing(Product::getPrice)
                .thenComparing(Product::getId))
                .forEach(p -> unique.putIfAbsent(p.menuVariantIdentity(), p));
        List<Product> displayProducts = new ArrayList<>(unique.values());
        if (min != null) {
            displayProducts.removeIf(p -> p.getPrice() == null || p.getPrice().compareTo(min) < 0);
        }
        if (max != null) {
            displayProducts.removeIf(p -> p.getPrice() == null || p.getPrice().compareTo(max) > 0);
        }

        displayProducts.sort(comparator(sort, matched));

        long total = displayProducts.size();
        int fromIndex = Math.min(page * size, displayProducts.size());
        int toIndex = Math.min(fromIndex + size, displayProducts.size());
        var items = displayProducts.subList(fromIndex, toIndex).stream().map(market::productView).toList();
        return new CatalogPage(items, total, page, size);
    }

public MenuOptions options(Long id) {
        var source = products.findById(id)
                .orElseThrow(() -> BusinessException.notFound(ErrorCode.PRODUCT_UNAVAILABLE, "Món không tồn tại"));

        Map<String, Product> unique = new LinkedHashMap<>();
        products.findAllByActiveTrue().stream()
                .sorted(Comparator.comparing(Product::getId))
                .forEach(p -> unique.putIfAbsent(p.menuVariantIdentity(), p));

        var selected = unique.get(source.menuVariantIdentity());
        if (selected == null) {
            throw BusinessException.badRequest(ErrorCode.PRODUCT_UNAVAILABLE, "Món đã ngừng bán");
        }

        var variants = unique.values().stream()
                .filter(p -> Product.normalizeSearch(p.getName()).equals(Product.normalizeSearch(selected.getName())))
                .sorted(Comparator.comparing(Product::getPrice))
                .map(market::productView)
                .toList();
        var toppings = unique.values().stream()
                .filter(p -> Product.normalizeSearch(p.getCategory().getName()).contains("topping"))
                .map(market::productView)
                .toList();
        boolean allowTopping = products.findAllByActiveTrue().stream().anyMatch(
                p -> p.menuVariantIdentity().equals(selected.menuVariantIdentity())
                        && Boolean.TRUE.equals(p.getCategory().getAllowTopping())
        );
        return new MenuOptions(
                market.productView(selected),
                variants,
                toppings,
                allowTopping && !Product.normalizeSearch(selected.getCategory().getName()).contains("topping")
        );
    }

public CartDto.CartResponse replaceCart(CurrentActor actor,CartDto.ReplaceCartRequest input,String version) {
        Account account=lock(actor);
        var cart=carts.findById(account.getId()).orElseGet(()->{var c=new AccountCart();c.setAccount(account);c.setAccountId(account.getId());return c;});
        if(version==null||!version.equals(Long.toString(cart.getRevision())))
            throw BusinessException.conflict(ErrorCode.CART_VERSION_CONFLICT,"Giỏ hàng đã thay đổi. Vui lòng tải lại trước khi sửa.");
        if(input==null||input.getItems()==null||input.getItems().size()>100) throw invalid("Giỏ tối đa 100 dòng");
        // Validate and reprice before storing only IDs, quantity and note.
        var candidates=products.findAllByActiveTrue();
        Map<String,CartDto.CartItemRequest> normalized=new LinkedHashMap<>();
        for(var line:input.getItems()) {
            lineView(line,false);
            Long productId=canonical(line.getProductId(),candidates);
            var toppingIds=(line.getToppingIds()==null?List.<Long>of():line.getToppingIds()).stream().map(t->canonical(t,candidates)).sorted().toList();
            String note=line.getNote()==null?"":line.getNote();
            String identity=available(productId,false).menuVariantIdentity();
            if(!toppingIds.isEmpty()&&candidates.stream().noneMatch(p->p.menuVariantIdentity().equals(identity)&&Boolean.TRUE.equals(p.getCategory().getAllowTopping())))throw invalid("Món không cho phép topping");
            String key=productId+"|"+toppingIds+"|"+note;
            var previous=normalized.get(key);
            if(previous==null)normalized.put(key,CartDto.CartItemRequest.builder().productId(productId).quantity(line.getQuantity()).note(note).toppingIds(toppingIds).build());
            else {previous.setQuantity(previous.getQuantity()+line.getQuantity());if(previous.getQuantity()>99)throw invalid("Mỗi lựa chọn món tối đa 99 ly");}
        }
        try {cart.setItemsJson(mapper.writeValueAsString(normalized.values()));}
        catch(Exception e){throw invalid("Dữ liệu giỏ không hợp lệ");}
        cart.setRevision(cart.getRevision()+1);
        carts.save(cart);
        return cartView(cart);
    }

public CartDto.CartResponse cart(CurrentActor actor) {
        var cart=carts.findById(accountId(actor)).orElseGet(AccountCart::new);
        return cartView(cart);
    }

public TableDto.TableContextResponse readByQr(String qrCode) {
        if (qrCode == null || qrCode.isBlank()) {
            throw BusinessException.badRequest(ErrorCode.QR_INVALID, "Mã QR không hợp lệ");
        }

        DiningTable table = tableRepository.findByQrCode(qrCode)
                .orElseThrow(() -> BusinessException.notFound(ErrorCode.TABLE_NOT_FOUND, "Không tìm thấy bàn"));

        if (!Boolean.TRUE.equals(table.getActive())) {
            throw BusinessException.badRequest(ErrorCode.TABLE_NOT_FOUND, "Bàn đang ngừng hoạt động");
        }

        var shop = branchService.tableBranch(table);
        TableDto.TableContextResponse.TableContextResponseBuilder builder = TableDto.TableContextResponse.builder()
                .shopId(shop.getId())
                .shopName(shop.getName())
                .tableId(table.getId())
                .tableName(table.getName())
                .qrCode(table.getQrCode())
                .status(table.getStatus());

        if (table.getActiveSessionId() != null) {
            Optional<TableSession> sessionOpt = sessionRepository.findById(table.getActiveSessionId());
            if (sessionOpt.isPresent() && sessionOpt.get().getStatus() == TableSessionStatus.OPEN) {
                TableSession session = sessionOpt.get();
                builder.sessionId(session.getId())
                        .sessionStatus(session.getStatus());

                // Cấp token truy cập phiên scoped riêng cho tab hiện tại (lưu hash, trả raw token)
                var issued = guestAccessService.issueTableSessionToken(session, 12);
                builder.tableToken(issued.rawToken());
            }
        }

        return builder.build();
    }

public Map<String,Object> quote(OrderDto.CreateCounterOrderRequest request, CurrentActor actor) {
        var shop = branchService.resolve(request.getShopId());
        branchService.assertCustomer(shop, actor);
        BigDecimal subtotal = BigDecimal.ZERO;
        for (var item : request.getItems()) {
            Product source = productRepository.findById(item.getProductId()).orElseThrow(() ->
                    BusinessException.badRequest(ErrorCode.PRODUCT_UNAVAILABLE,"Món không tồn tại"));
            Product product = branchService.product(source, shop);
            if (!Boolean.TRUE.equals(product.getActive())) throw BusinessException.badRequest(ErrorCode.PRODUCT_UNAVAILABLE,"Món ngừng bán");
            BigDecimal price = product.getPrice();
            if (item.getToppingIds() != null) for (Long id : item.getToppingIds()) {
                var topping = branchService.product(productRepository.findById(id).orElseThrow(() ->
                        BusinessException.badRequest(ErrorCode.PRODUCT_UNAVAILABLE,"Topping không tồn tại")), shop);
                if (!Boolean.TRUE.equals(topping.getActive())) throw BusinessException.badRequest(ErrorCode.PRODUCT_UNAVAILABLE,"Topping ngừng bán");
                price = price.add(topping.getPrice());
            }
            subtotal = subtotal.add(price.multiply(BigDecimal.valueOf(item.getQuantity())));
        }
        var draft = Order.builder().shop(shop).account(actor != null && actor.isAuthenticated()
                ? accountRepository.findById(actor.getAccountId()).orElse(null) : null).build();
        var discount = applyVoucher(draft, request.getVoucherCode(), subtotal,
                computeDiscount(subtotal, settingsRepository.findById(1).orElse(null)), false);
        return Map.of("shopId",shop.getId(),"subtotal",subtotal,"discountAmount",discount.discountAmount,"totalAmount",discount.totalAmount,"shippingFee",BigDecimal.ZERO);
    }

public OrderDto.OrderResponse createCounterOrder(OrderDto.CreateCounterOrderRequest request, CurrentActor actor, String idempotencyKey) {
        if (idempotencyKey != null && (idempotencyKey.isBlank() || idempotencyKey.length() > 64))
            throw BusinessException.badRequest(ErrorCode.VALIDATION_FAILED,"Mã yêu cầu không hợp lệ");
        if (idempotencyKey == null) idempotencyKey = UUID.randomUUID().toString();
        var shop = branchService.resolve(request.getShopId());
        branchService.assertCustomer(shop, actor);
        if (actor != null && (actor.hasRole(Role.ADMIN) || actor.hasRole(Role.CASHIER)))
            branchService.assertStaff(Order.builder().shop(shop).build(), actor.getAccountId());
        String fingerprint = fingerprint(request);
        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            var existing = orderRepository.findByIdempotencyKey(idempotencyKey);
            if (existing.isPresent()) {
                Order order = existing.get();
                assertReplayAccess(order,actor,OrderSource.COUNTER);
                assertFingerprint(order, fingerprint);
                Invoice invoice = invoiceRepository.findByOrderId(order.getId()).orElse(null);
                List<OrderItem> items = orderItemRepository.findByOrderId(order.getId());
                return mapToOrderResponse(order, invoice, items, null, null);
            }
        }
        Account creator = (actor != null && actor.isAuthenticated()) ?
                accountRepository.findById(actor.getAccountId()).orElse(null) : null;
        Order order = Order.builder()
                .session(null)
                .account(creator)
                .source(OrderSource.COUNTER)
                .status(actor != null && (actor.hasRole(Role.CASHIER) || actor.hasRole(Role.ADMIN))
                        ? OrderStatus.CHO_THANH_TOAN : OrderStatus.CHO_XAC_NHAN)
                .note(request.getNote())
                .idempotencyKey(idempotencyKey)
                .shop(shop)
                .requestedPaymentMethod(request.getPaymentMethod() != null ? request.getPaymentMethod() : PaymentMethod.CASH)
                .requestFingerprint(fingerprint)
                .createdAt(Instant.now())
                .version(0L)
                .build();
        order = orderRepository.save(order);
        List<OrderItem> savedItems = createOrderItemsAndSnapshots(order, request.getItems());
        BigDecimal subtotal = calculateOrderSubtotal(savedItems);
        GlobalSettings settings = settingsRepository.findById(1).orElse(null);
        CalculatedDiscount discount = computeDiscount(subtotal, settings);
        discount = applyVoucher(order, request.getVoucherCode(), subtotal, discount, true);
        if (request.getExpectedTotal() != null && request.getExpectedTotal().compareTo(discount.totalAmount) != 0)
            throw BusinessException.conflict(ErrorCode.VALIDATION_FAILED, "Giá hoặc giảm giá đã thay đổi. Vui lòng kiểm tra tổng tiền mới.");
        Invoice invoice = Invoice.builder()
                .order(order)
                .subtotal(subtotal)
                .discountAmount(discount.discountAmount)
                .totalAmount(discount.totalAmount)
                .snapshotDiscountPercent(discount.snapshotPercent)
                .snapshotDiscountType(discount.discountType)
                .snapshotDiscountValue(discount.configValue)
                .status(InvoiceStatus.HIEU_LUC)
                .createdAt(Instant.now())
                .build();
        invoice = invoiceRepository.save(invoice);
        var issued = guestAccessService.issueCounterOrderToken(order, 24);
        auditRepository.save(BusinessAudit.builder()
                .orderId(order.getId())
                .accountId(creator != null ? creator.getId() : null)
                .action("COUNTER_ORDER_CREATED")
                .afterState(order.getStatus().name())
                .createdAt(Instant.now())
                .build());
        realtimeEventPublisher.publishAfterCommit("/topic/cashier", "ORDER_CREATED", order.getId().toString(), null, "1", Map.of("orderId", order.getId(), "status", order.getStatus().name()));
        return mapToOrderResponse(order, invoice, savedItems, null, issued.rawToken());
    }

public OrderDto.OrderResponse createTableOrder(OrderDto.CreateTableOrderRequest request, CurrentActor actor, String idempotencyKey) {
        if (idempotencyKey != null && (idempotencyKey.isBlank() || idempotencyKey.length() > 64))
            throw BusinessException.badRequest(ErrorCode.VALIDATION_FAILED,"Mã yêu cầu không hợp lệ");
        if (idempotencyKey == null) idempotencyKey = UUID.randomUUID().toString();
        if (request == null || request.getTableId() == null)
            throw BusinessException.forbidden(ErrorCode.ACCESS_DENIED,"Hãy quét mã QR bàn hợp lệ");
        DiningTable table = tableRepository.findByIdWithLock(request.getTableId())
                .orElseThrow(() -> BusinessException.notFound(ErrorCode.TABLE_NOT_FOUND, "Không tìm thấy bàn"));
        boolean staff = actor != null && (actor.hasRole(Role.CASHIER) || actor.hasRole(Role.ADMIN));
        if (!staff) {
            boolean qrValid = request.getQrCode() != null && !request.getQrCode().isBlank()
                    && java.security.MessageDigest.isEqual(request.getQrCode().getBytes(java.nio.charset.StandardCharsets.UTF_8),
                        table.getQrCode().getBytes(java.nio.charset.StandardCharsets.UTF_8));
            var proof = guestAccessService.validateTableToken(request.getTableToken());
            boolean sessionValid = proof.isPresent() && proof.get().getSession().getTable().getId().equals(table.getId())
                    && Objects.equals(table.getActiveSessionId(), proof.get().getSession().getId());
            if (!qrValid && !sessionValid) throw BusinessException.forbidden(ErrorCode.ACCESS_DENIED, "Hãy quét mã QR bàn hợp lệ");
        }
        var shop = branchService.tableBranch(table);
        branchService.assertCustomer(shop, actor);
        if (request.getShopId() != null && !request.getShopId().equals(shop.getId()))
            throw BusinessException.forbidden(ErrorCode.ACCESS_DENIED, "Không được đổi cơ sở của bàn");
        if (staff) branchService.assertStaff(Order.builder().shop(shop).build(), actor.getAccountId());
        String fingerprint = fingerprint(request);
        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            var existing = orderRepository.findByIdempotencyKey(idempotencyKey);
            if (existing.isPresent()) {
                Order order = existing.get();
                assertReplayAccess(order,actor,OrderSource.TABLE);
                assertFingerprint(order, fingerprint);
                Invoice invoice = invoiceRepository.findByOrderId(order.getId()).orElse(null);
                List<OrderItem> items = orderItemRepository.findByOrderId(order.getId());
                return mapToOrderResponse(order, invoice, items, null, null);
            }
        }

        if (!Boolean.TRUE.equals(table.getActive())) {
            throw BusinessException.badRequest(ErrorCode.TABLE_NOT_FOUND, "Bàn đang ngừng hoạt động");
        }
        // Kiểm tra expectedSessionId
        TableSession session;
        String rawGuestTableToken = null;
        if (table.getActiveSessionId() == null) {
            if (request.getExpectedSessionId() != null) {
                throw BusinessException.conflict(ErrorCode.TABLE_SESSION_CHANGED, "Bàn chưa có phiên hoặc phiên đã kết thúc");
            }
            // Mở phiên mới
            Account opener = (actor != null && actor.isAuthenticated()) ?
                    accountRepository.findById(actor.getAccountId()).orElse(null) : null;
            session = TableSession.builder()
                    .table(table)
                    .status(TableSessionStatus.OPEN)
                    .openedAt(Instant.now())
                    .openedBy(opener)
                    .version(0L)
                    .build();
            session = sessionRepository.save(session);
            table.setStatus(TableStatus.CO_KHACH);
            table.setActiveSessionId(session.getId());
            tableRepository.save(table);
            SessionCart cart = SessionCart.builder()
                    .session(session)
                    .version(1L)
                    .modifiedAt(Instant.now())
                    .build();
            cartRepository.save(cart);
            var issued = guestAccessService.issueTableSessionToken(session, 12);
            rawGuestTableToken = issued.rawToken();
        } else {
            if (request.getExpectedSessionId() == null) {
                throw BusinessException.conflict(ErrorCode.TABLE_SESSION_CHANGED, "Bàn đã có khách đang phục vụ. Vui lòng tải lại.");
            }
            if (!table.getActiveSessionId().equals(request.getExpectedSessionId())) {
                throw BusinessException.conflict(ErrorCode.TABLE_SESSION_CHANGED, "Phiên bàn đã thay đổi");
            }
            session = sessionRepository.findById(table.getActiveSessionId())
                    .orElseThrow(() -> BusinessException.conflict(ErrorCode.TABLE_SESSION_CHANGED, "Không tìm thấy phiên"));
        }
        if (session.getStatus() != TableSessionStatus.OPEN || !session.getTable().getId().equals(table.getId()))
            throw BusinessException.conflict(ErrorCode.TABLE_SESSION_CHANGED,"Phiên bàn đã kết thúc hoặc không thuộc bàn này");
        // Tạo đơn hàng và tính giá snapshot
        Account customerAccount = (actor != null && actor.isAuthenticated()) ?
                accountRepository.findById(actor.getAccountId()).orElse(null) : null;
        Order order = Order.builder()
                .session(session)
                .account(customerAccount)
                .source(OrderSource.TABLE)
                .status(actor != null && (actor.hasRole(Role.CASHIER) || actor.hasRole(Role.ADMIN))
                        ? OrderStatus.CHO_THANH_TOAN : OrderStatus.CHO_XAC_NHAN)
                .idempotencyKey(idempotencyKey)
                .shop(shop)
                .requestedPaymentMethod(request.getPaymentMethod() != null ? request.getPaymentMethod() : PaymentMethod.CASH)
                .requestFingerprint(fingerprint)
                .createdAt(Instant.now())
                .version(0L)
                .build();
        order = orderRepository.save(order);
        List<OrderItem> savedItems = createOrderItemsAndSnapshots(order, request.getItems());
        // Tính toán tổng tiền và giảm giá từ GlobalSettings
        BigDecimal subtotal = calculateOrderSubtotal(savedItems);
        GlobalSettings settings = settingsRepository.findById(1).orElse(null);
        CalculatedDiscount discount = computeDiscount(subtotal, settings);
        discount = applyVoucher(order, request.getVoucherCode(), subtotal, discount, true);
        if (request.getExpectedTotal() != null && request.getExpectedTotal().compareTo(discount.totalAmount) != 0)
            throw BusinessException.conflict(ErrorCode.VALIDATION_FAILED, "Giá hoặc giảm giá đã thay đổi. Vui lòng kiểm tra tổng tiền mới.");
        Invoice invoice = Invoice.builder()
                .order(order)
                .subtotal(subtotal)
                .discountAmount(discount.discountAmount)
                .totalAmount(discount.totalAmount)
                .snapshotDiscountPercent(discount.snapshotPercent)
                .snapshotDiscountType(discount.discountType)
                .snapshotDiscountValue(discount.configValue)
                .status(InvoiceStatus.HIEU_LUC)
                .createdAt(Instant.now())
                .build();
        invoice = invoiceRepository.save(invoice);
        // Cập nhật phần còn lại của giỏ hàng trên server
        if (staff) sessionCartService.replaceCart(session.getId(),
                new CartDto.ReplaceCartRequest(request.getRemainingCartItems() != null ? request.getRemainingCartItems() : Collections.emptyList()),
                null);
        auditRepository.save(BusinessAudit.builder()
                .sessionId(session.getId())
                .orderId(order.getId())
                .accountId(customerAccount != null ? customerAccount.getId() : null)
                .action("ORDER_CREATED")
                .afterState(order.getStatus().name())
                .createdAt(Instant.now())
                .build());
        realtimeEventPublisher.publishAfterCommit("/topic/cashier", "ORDER_CREATED", order.getId().toString(), session.getId().toString(), "1", Map.of("orderId", order.getId(), "status", order.getStatus().name()));
        realtimeEventPublisher.publishAfterCommit("/topic/table-sessions/" + session.getId(), "ORDER_CREATED", order.getId().toString(), session.getId().toString(), "1", Map.of("orderId", order.getId(), "status", order.getStatus().name()));
        // Per-order guest proof: order tracking must never reuse a table-wide access token.
        var receiptToken = guestAccessService.issueCounterOrderToken(order, 24);
        return mapToOrderResponse(order, invoice, savedItems, rawGuestTableToken, receiptToken.rawToken());
    }

