public ReviewView create(CurrentActor actor,Long productId,ReviewInput input){
  Long accountId=CustomerDataService.accountId(actor);
  var account=accounts.findByIdWithLock(accountId).orElseThrow(()->invalid("Không có tài khoản"));
  if(input.comment().trim().length()<50)throw invalid("Bình luận tối thiểu 50 ký tự");
  if(reviews.existsByAccountIdAndProductId(accountId,productId))throw BusinessException.conflict(ErrorCode.VALIDATION_FAILED,"Bạn đã đánh giá món này");
  var product=products.findById(productId).orElseThrow(()->invalid("Món không tồn tại"));
  ProductReview r=new ProductReview();r.setAccount(account);r.setProduct(product);r.setStars(input.stars());r.setComment(input.comment().trim());
  if(input.delivery()){
   var order=deliveries.findById(input.orderId()).orElseThrow(()->invalid("Không có đơn hàng"));
   if(!order.getAccount().getId().equals(accountId)||order.getStatus()!=DeliveryOrder.Status.DELIVERED||!order.isPaid()||order.getLines().stream().noneMatch(l->l.getProduct().getId().equals(productId)))throw BusinessException.forbidden(ErrorCode.ACCESS_DENIED,"Chỉ đánh giá món đã mua và nhận thành công");
   r.setDeliveryOrder(order);
  }else{
   long eligible=em.createQuery("select count(i) from OrderItem i, Payment pay where i.order.id=:orderId and i.product.id=:productId and i.order.account.id=:accountId and i.order.status=vn.edu.ute.milktea.entity.order.OrderStatus.HOAN_THANH and pay.invoice.order=i.order and pay.invoice.status=vn.edu.ute.milktea.entity.order.InvoiceStatus.HIEU_LUC and pay.amount>=pay.invoice.totalAmount",Long.class)
    .setParameter("orderId",input.orderId()).setParameter("productId",productId).setParameter("accountId",accountId).getSingleResult();
   if(eligible==0)throw BusinessException.forbidden(ErrorCode.ACCESS_DENIED,"Chỉ đánh giá món đã mua, hoàn thành và thanh toán");
   r.setCounterOrder(counterOrders.findById(input.orderId()).orElseThrow(()->invalid("Không có đơn hàng")));
  }
  return view(reviews.save(r));
 }

public ReviewView media(CurrentActor actor,Long reviewId,MultipartFile file){
  Long accountId=CustomerDataService.accountId(actor);accounts.findByIdWithLock(accountId).orElseThrow(()->invalid("Không có tài khoản"));
  var review=reviews.findById(reviewId).orElseThrow(()->invalid("Không có đánh giá"));
  if(!review.getAccount().getId().equals(accountId))throw BusinessException.forbidden(ErrorCode.ACCESS_DENIED,"Không có quyền sửa đánh giá");
  if(review.getMedia().size()>=5)throw invalid("Mỗi đánh giá tối đa 5 ảnh/video");
  if(file==null||file.isEmpty()||file.getSize()>20*1024*1024)throw invalid("Ảnh/video không hợp lệ hoặc vượt 20MB");
  if(!images.isCloudinaryConfigured())throw invalid("Chưa cấu hình Cloudinary để tải ảnh/video");
  try{
   byte[] bytes=file.getBytes();String mime=Objects.toString(file.getContentType(),"");String type;
   boolean jpeg=bytes.length>=3&&(bytes[0]&255)==255&&(bytes[1]&255)==216&&(bytes[2]&255)==255;
   boolean png=bytes.length>=8&&Arrays.equals(Arrays.copyOf(bytes,8),new byte[]{(byte)137,80,78,71,13,10,26,10});
   boolean webp=bytes.length>=12&&new String(bytes,0,4,java.nio.charset.StandardCharsets.US_ASCII).equals("RIFF")&&new String(bytes,8,4,java.nio.charset.StandardCharsets.US_ASCII).equals("WEBP");
   boolean mp4=bytes.length>=12&&new String(bytes,4,4,java.nio.charset.StandardCharsets.US_ASCII).equals("ftyp");
   if((jpeg&&mime.equals("image/jpeg"))||(png&&mime.equals("image/png"))||(webp&&mime.equals("image/webp"))){type="image";if(bytes.length>5*1024*1024)throw invalid("Ảnh tối đa 5MB");}
   else if(mp4&&mime.equals("video/mp4"))type="video";else throw invalid("Chỉ nhận JPEG, PNG, WebP hoặc MP4 có nội dung hợp lệ");
   String publicId="ute-tea/reviews/"+UUID.randomUUID();
   var uploaded=cloudinary.uploader().upload(bytes,Map.of("resource_type",type,"public_id",publicId,"overwrite",false));
   TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public void afterCompletion(int status){if(status!=STATUS_COMMITTED)try{cloudinary.uploader().destroy(publicId,Map.of("resource_type",type));}catch(Exception ignored){}}});
   var media=new ReviewMedia();media.setReview(review);media.setMediaType(type);media.setPublicId(publicId);media.setUrl((String)uploaded.get("secure_url"));review.getMedia().add(media);reviews.saveAndFlush(review);return view(review);
  }catch(BusinessException e){throw e;}catch(Exception e){throw BusinessException.badRequest(ErrorCode.IMAGE_UPLOAD_FAILED,"Không thể tải ảnh/video. Vui lòng thử lại.");}
 }

public CustomerDataDto.AddressView saveAddress(CurrentActor actor,Long id,CustomerDataDto.AddressInput input) {
        Account account=lock(actor);
        var existing=addresses.findByAccountIdOrderByIdAsc(account.getId());
        if(id==null&&existing.size()>=20)throw invalid("Tối đa 20 địa chỉ");
        var address=id==null?new DeliveryAddress():addresses.findByIdAndAccountId(id,account.getId()).orElseThrow(()->BusinessException.notFound(ErrorCode.ACCESS_DENIED,"Không tìm thấy địa chỉ"));
        boolean makeDefault=input.defaultAddress()||existing.isEmpty()||address.isDefaultAddress();
        if(makeDefault){existing.forEach(a->a.setDefaultAddress(false));addresses.flush();}
        address.setAccount(account);address.setRecipient(input.recipient().trim());address.setPhone(input.phone().trim());
        address.setAddressLine(input.addressLine().trim());address.setDefaultAddress(makeDefault);
        address.setArea(input.area()==null?null:input.area().trim());address.setLatitude(input.latitude());address.setLongitude(input.longitude());
        return addressView(addresses.save(address));
    }

public List<OrderDto.OrderResponse> getOrdersForCashier(OrderStatus status, String paymentStatus, String tab, String query) {
        List<Order> orders;
        boolean isAllTab = (tab == null || tab.isBlank() || "all".equalsIgnoreCase(tab));
        if (isAllTab && status != null) {
            orders = orderRepository.findByStatusInOrderByCreatedAtAsc(List.of(status));
        } else {
            orders = orderRepository.findAll();
        }
        var stream = orders.stream().filter(this::staffCanRead)
                .sorted(java.util.Comparator.comparing(Order::getCreatedAt).reversed())
                .map(this::mapOrderToResponse);
        if (query != null && !query.isBlank()) {
            String q = query.trim().toUpperCase().replaceFirst("^#", "");
            stream = stream.filter(o -> {
                String code = "ORD" + String.format("%03d", o.getOrderId());
                return code.contains(q) || String.valueOf(o.getOrderId()).equals(q)
                        || (o.getTableName() != null && o.getTableName().toUpperCase().contains(q))
                        || (o.getCustomerName() != null && o.getCustomerName().toUpperCase().contains(q));
            });
        }
        if (!isAllTab) {
            stream = stream.filter(o -> matchesTab(o, tab));
        } else {
            if (status != null) {
                stream = stream.filter(o -> o.getStatus() == status);
            }
            if (paymentStatus != null && !paymentStatus.isBlank()) {
                String ps = paymentStatus.trim().toUpperCase();
                if ("PAID".equals(ps)) {
                    stream = stream.filter(OrderDto.OrderResponse::isPaid);
                } else if ("PAID_TM".equals(ps) || "PAID_CASH".equals(ps)) {
                    stream = stream.filter(o -> o.isPaid() && (!"BANK_TRANSFER".equalsIgnoreCase(o.getPaymentMethod()) && !o.isTransferNotified()));
                } else if ("PAID_CK".equals(ps) || "PAID_TRANSFER".equals(ps) || "PAID_BANK_TRANSFER".equals(ps)) {
                    stream = stream.filter(o -> o.isPaid() && ("BANK_TRANSFER".equalsIgnoreCase(o.getPaymentMethod()) || o.isTransferNotified()));
                } else if ("UNPAID".equals(ps)) {
                    stream = stream.filter(o -> !o.isPaid() && o.getStatus() != OrderStatus.DA_HUY);
                } else if ("TRANSFER_PENDING".equals(ps)) {
                    stream = stream.filter(o -> o.isTransferNotified() && !o.isPaid());
                }
            }
        }
        return stream.toList();
    }

public void confirm(Long orderId, Long cashierId) {
        Order order = orderRepository.findByIdWithLock(orderId)
                .orElseThrow(() -> BusinessException.notFound(ErrorCode.ORDER_STATE_CONFLICT, "Không tìm thấy đơn hàng"));
        branchService.assertStaff(order, cashierId);
        if (order.getStatus() == OrderStatus.CHO_CHE_BIEN) {
            return;
        }
        if (order.getStatus() != OrderStatus.CHO_XAC_NHAN) {
            throw BusinessException.conflict(ErrorCode.ORDER_STATE_CONFLICT,
                    "Không thể xác nhận đơn ở trạng thái: " + order.getStatus());
        }
        order.setStatus(OrderStatus.CHO_CHE_BIEN);
        Invoice invoice = invoiceRepository.findByOrderId(orderId)
                .orElseThrow(() -> BusinessException.notFound(
                        ErrorCode.ORDER_STATE_CONFLICT,
                        "Không tìm thấy hóa đơn của đơn hàng"));
        // Không áp dụng paid gate: Hỗ trợ tiền mặt hoặc chuyển khoản trước/trong/sau pha chế theo GEMINI.md
        orderRepository.save(order);
        auditRepository.save(BusinessAudit.builder()
                .orderId(order.getId())
                .accountId(cashierId)
                .action("ORDER_CONFIRMED")
                .beforeState("CHO_XAC_NHAN")
                .afterState("CHO_CHE_BIEN")
                .createdAt(Instant.now())
                .build());
        String sId = order.getSession() != null ? order.getSession().getId().toString() : null;
        realtimeEventPublisher.publishAfterCommit("/topic/kitchen", "ORDER_STATUS_CHANGED", order.getId().toString(), sId, "1", Map.of("orderId", order.getId(), "status", order.getStatus().name()));
        realtimeEventPublisher.publishAfterCommit("/topic/cashier", "ORDER_STATUS_CHANGED", order.getId().toString(), sId, "1", Map.of("orderId", order.getId(), "status", order.getStatus().name()));
        if (order.getSession() != null) {
            realtimeEventPublisher.publishAfterCommit("/topic/table-sessions/" + order.getSession().getId(), "ORDER_STATUS_CHANGED", order.getId().toString(), sId, "1", Map.of("orderId", order.getId(), "status", order.getStatus().name()));
        }
    }

public OrderDto.OrderResponse createCounterOrder(OrderDto.CreateCounterOrderRequest request, CurrentActor actor, String idempotencyKey) {
        if (idempotencyKey != null && (idempotencyKey.isBlank() || idempotencyKey.length() > 64))
            throw BusinessException.badRequest(ErrorCode.VALIDATION_FAILED,"Mã yêu cầu không hợp lệ");
        if (idempotencyKey == null) idempotencyKey = UUID.randomUUID().toString();
        var shop = branchService.resolve(request.getShopId());
        branchService.assertCustomer(shop, actor);
        if (actor != null && (actor.hasRole(Role.ADMIN) || actor.hasRole(Role.CASHIER)))
            branchService.assertStaff(Order.builder().shop(shop).build(), actor.getAccountId());
        String fingerprint = fingerprint(request);
        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            var existing = orderRepository.findByIdempotencyKey(idempotencyKey);
            if (existing.isPresent()) {
                Order order = existing.get();
                assertReplayAccess(order,actor,OrderSource.COUNTER);
                assertFingerprint(order, fingerprint);
                Invoice invoice = invoiceRepository.findByOrderId(order.getId()).orElse(null);
                List<OrderItem> items = orderItemRepository.findByOrderId(order.getId());
                return mapToOrderResponse(order, invoice, items, null, null);
            }
        }
        Account creator = (actor != null && actor.isAuthenticated()) ?
                accountRepository.findById(actor.getAccountId()).orElse(null) : null;
        Order order = Order.builder()
                .session(null)
                .account(creator)
                .source(OrderSource.COUNTER)
                .status(actor != null && (actor.hasRole(Role.CASHIER) || actor.hasRole(Role.ADMIN))
                        ? OrderStatus.CHO_THANH_TOAN : OrderStatus.CHO_XAC_NHAN)
                .note(request.getNote())
                .idempotencyKey(idempotencyKey)
                .shop(shop)
                .requestedPaymentMethod(request.getPaymentMethod() != null ? request.getPaymentMethod() : PaymentMethod.CASH)
                .requestFingerprint(fingerprint)
                .createdAt(Instant.now())
                .version(0L)
                .build();
        order = orderRepository.save(order);
        List<OrderItem> savedItems = createOrderItemsAndSnapshots(order, request.getItems());
        BigDecimal subtotal = calculateOrderSubtotal(savedItems);
        GlobalSettings settings = settingsRepository.findById(1).orElse(null);
        CalculatedDiscount discount = computeDiscount(subtotal, settings);
        discount = applyVoucher(order, request.getVoucherCode(), subtotal, discount, true);
        if (request.getExpectedTotal() != null && request.getExpectedTotal().compareTo(discount.totalAmount) != 0)
            throw BusinessException.conflict(ErrorCode.VALIDATION_FAILED, "Giá hoặc giảm giá đã thay đổi. Vui lòng kiểm tra tổng tiền mới.");
        Invoice invoice = Invoice.builder()
                .order(order)
                .subtotal(subtotal)
                .discountAmount(discount.discountAmount)
                .totalAmount(discount.totalAmount)
                .snapshotDiscountPercent(discount.snapshotPercent)
                .snapshotDiscountType(discount.discountType)
                .snapshotDiscountValue(discount.configValue)
                .status(InvoiceStatus.HIEU_LUC)
                .createdAt(Instant.now())
                .build();
        invoice = invoiceRepository.save(invoice);
        var issued = guestAccessService.issueCounterOrderToken(order, 24);
        auditRepository.save(BusinessAudit.builder()
                .orderId(order.getId())
                .accountId(creator != null ? creator.getId() : null)
                .action("COUNTER_ORDER_CREATED")
                .afterState(order.getStatus().name())
                .createdAt(Instant.now())
                .build());
        realtimeEventPublisher.publishAfterCommit("/topic/cashier", "ORDER_CREATED", order.getId().toString(), null, "1", Map.of("orderId", order.getId(), "status", order.getStatus().name()));
        return mapToOrderResponse(order, invoice, savedItems, null, issued.rawToken());
    }

public PaymentDto.PaymentResponse recordReceipt(
            Long invoiceId,
            PaymentDto.RecordPaymentRequest request,
            Long cashierId,
            String idempotencyKey) {

        // 1. Kiểm tra dữ liệu đầu vào
        if (request == null || request.getMethod() == null) {
            throw BusinessException.conflict(
                    ErrorCode.VALIDATION_FAILED,
                    "Phương thức thanh toán không hợp lệ");
        }

        if (idempotencyKey != null
                && idempotencyKey.length() > 64) {
            throw BusinessException.conflict(
                    ErrorCode.VALIDATION_FAILED,
                    "Mã yêu cầu thanh toán quá dài");
        }

        // 2. Đọc hóa đơn để xác định đơn hàng
        Invoice invoiceLookup = invoiceRepository.findById(invoiceId)
                .orElseThrow(() -> BusinessException.notFound(
                        ErrorCode.VALIDATION_FAILED,
                        "Không tìm thấy hóa đơn"));

        // Lock table before order/invoice to match table order creation and settlement.
        if (invoiceLookup.getOrder().getSession() != null) {
            tableRepository.findByIdWithLock(invoiceLookup.getOrder().getSession().getTable().getId())
                    .orElseThrow(() -> BusinessException.notFound(ErrorCode.TABLE_NOT_FOUND, "Không tìm thấy bàn"));
        }
        // 3. Khóa Order trước, sau đó khóa Invoice
        Order order = orderRepository.findByIdWithLock(
                        invoiceLookup.getOrder().getId())
                .orElseThrow(() -> BusinessException.notFound(
                        ErrorCode.VALIDATION_FAILED,
                        "Không tìm thấy đơn hàng"));

        Invoice invoice = invoiceRepository.findByIdWithLock(invoiceId)
                .orElseThrow(() -> BusinessException.notFound(
                        ErrorCode.VALIDATION_FAILED,
                        "Không tìm thấy hóa đơn"));

        branchService.assertStaff(order, cashierId);

        // 4. Xử lý request gửi lại với cùng idempotency key
        if (idempotencyKey != null
                && !idempotencyKey.isBlank()) {

            var existing = paymentRepository
                    .findByIdempotencyKey(idempotencyKey);

            if (existing.isPresent()) {
                Payment oldPayment = existing.get();

                // Không cho tái sử dụng key của hóa đơn khác
                if (!oldPayment.getInvoice().getId()
                        .equals(invoiceId)) {
                    throw BusinessException.conflict(
                            ErrorCode.IDEMPOTENCY_CONFLICT,
                            "Mã yêu cầu đã được dùng cho hóa đơn khác");
                }

                // Không cho đổi phương thức trong cùng một key
                if (oldPayment.getMethod() != request.getMethod()) {
                    throw BusinessException.conflict(
                            ErrorCode.IDEMPOTENCY_CONFLICT,
                            "Mã yêu cầu đã được dùng với phương thức khác");
                }

                return toPaymentResponse(oldPayment);
            }
        }

        // 5. Kiểm tra trạng thái hóa đơn
        if (invoice.getStatus() != InvoiceStatus.HIEU_LUC) {
            throw BusinessException.conflict(
                    ErrorCode.ORDER_STATE_CONFLICT,
                    "Hóa đơn đã bị hủy, không thể thu tiền");
        }

        if (order.getStatus() == OrderStatus.DA_HUY) {
            throw BusinessException.conflict(ErrorCode.ORDER_STATE_CONFLICT, "Không thể thu tiền đơn đã hủy");
        }
        OrderStatus previousStatus = order.getStatus();

        // 8. Không ghi khoản thu thứ hai cho cùng hóa đơn
        if (paymentRepository.existsByInvoiceId(invoiceId)) {
            throw BusinessException.conflict(
                    ErrorCode.PAYMENT_ALREADY_RECORDED,
                    "Hóa đơn đã được thanh toán");
        }

        // 9. Kiểm tra số tiền hóa đơn
        if (invoice.getTotalAmount() == null
                || invoice.getTotalAmount().signum() <= 0) {
            throw BusinessException.conflict(
                    ErrorCode.VALIDATION_FAILED,
                    "Số tiền phải trả không hợp lệ");
        }

        // 10. Xác định nhân viên thu ngân
        if (cashierId == null) {
            throw BusinessException.conflict(
                    ErrorCode.ACCESS_DENIED,
                    "Chưa xác định nhân viên thu tiền");
        }

        Account cashier = accountRepository.findById(cashierId)
                .orElseThrow(() -> BusinessException.notFound(
                        ErrorCode.VALIDATION_FAILED,
                        "Không tìm thấy nhân viên thu tiền"));

        // 11. Tạo Payment bằng số tiền server đã chốt
        Payment payment = Payment.builder()
                .invoice(invoice)
                .method(request.getMethod())
                .amount(invoice.getTotalAmount())
                .reference(request.getReference())
                .recordedBy(cashier)
                .paidAt(Instant.now())
                .idempotencyKey(idempotencyKey)
                .build();

        payment = paymentRepository.save(payment);

        // 12. Chuyển trạng thái trong cùng transaction
        if (order.getStatus() == OrderStatus.CHO_THANH_TOAN) {
            order.setStatus(isStaffCreated(order) ? OrderStatus.CHO_CHE_BIEN : OrderStatus.CHO_XAC_NHAN);
        }
        orderRepository.save(order);

        // 13. Ghi lịch sử nghiệp vụ
        auditRepository.save(BusinessAudit.builder()
                .orderId(order.getId())
                .accountId(cashierId)
                .action("PAYMENT_RECORDED")
                .beforeState(previousStatus.name())
                .afterState(order.getStatus().name())
                .reason("Ghi thu " + request.getMethod()
                        + ": " + payment.getAmount() + " VND")
                .createdAt(Instant.now())
                .build());

        // 14. Phát sự kiện sau khi transaction commit
        String sessionId = order.getSession() != null
                ? order.getSession().getId().toString()
                : null;

        java.util.Map<String, Object> eventData =
                java.util.Map.of(
                        "orderId", order.getId(),
                        "invoiceId", invoice.getId(),
                        "amount", payment.getAmount(),
                        "status", order.getStatus().name());

        realtimeEventPublisher.publishAfterCommit(
                "/topic/cashier",
                "PAYMENT_RECORDED",
                payment.getId().toString(),
                sessionId,
                "1",
                eventData);

        if (order.getStatus() == OrderStatus.CHO_CHE_BIEN) {
            realtimeEventPublisher.publishAfterCommit("/topic/kitchen", "ORDER_STATUS_CHANGED",
                    order.getId().toString(), sessionId, "1", eventData);
        }

        if (order.getSession() != null) {
            realtimeEventPublisher.publishAfterCommit(
                    "/topic/table-sessions/"
                            + order.getSession().getId(),
                    "PAYMENT_RECORDED",
                    payment.getId().toString(),
                    sessionId,
                    "1",
                    eventData);
        }

        return toPaymentResponse(payment);
    }

public PaymentDto.PaymentResponse confirmTransferReceiptForOrder(Long orderId, Long cashierId, String idempotencyKey) {
        Invoice invoice = invoiceRepository.findByOrderId(orderId)
                .orElseThrow(() -> BusinessException.notFound(ErrorCode.VALIDATION_FAILED, "Không tìm thấy hóa đơn cho đơn hàng #" + orderId));
        branchService.assertStaff(invoice.getOrder(), cashierId);
        if (paymentRepository.existsByInvoiceId(invoice.getId())) {
            Payment existing = paymentRepository.findByInvoiceId(invoice.getId()).orElse(null);
            if (existing != null) {
                return toPaymentResponse(existing);
            }
        }
        PaymentDto.RecordPaymentRequest request = PaymentDto.RecordPaymentRequest.builder()
                .method(PaymentMethod.BANK_TRANSFER)
                .reference("TRANSFER_CONFIRMED_" + orderId)
                .build();
        String effectiveKey = (idempotencyKey != null && !idempotencyKey.isBlank())
                ? idempotencyKey
                : "TRANSFER_CONFIRM_" + orderId;
        return recordReceipt(invoice.getId(), request, cashierId, effectiveKey);
    }

public TableSession openByCashier(Long tableId, Long cashierId) {
        DiningTable table = tableRepository.findByIdWithLock(tableId)
                .orElseThrow(() -> BusinessException.notFound(ErrorCode.TABLE_NOT_FOUND, "Không tìm thấy bàn"));
        if (table.getShop() != null) branchService.assertStaff(Order.builder().shop(table.getShop()).build(), cashierId);

        if (table.getActiveSessionId() != null) {
            var existingOpt = sessionRepository.findById(table.getActiveSessionId());
            if (existingOpt.isPresent() && existingOpt.get().getStatus() == TableSessionStatus.OPEN) {
                return existingOpt.get();
            }
        }

        Account cashier = cashierId != null ? accountRepository.findById(cashierId).orElse(null) : null;

        TableSession session = TableSession.builder()
                .table(table)
                .status(TableSessionStatus.OPEN)
                .openedAt(Instant.now())
                .openedBy(cashier)
                .version(0L)
                .build();
        session = sessionRepository.save(session);

        table.setStatus(TableStatus.CO_KHACH);
        table.setActiveSessionId(session.getId());
        tableRepository.save(table);

        SessionCart cart = SessionCart.builder()
                .session(session)
                .version(1L)
                .modifiedAt(Instant.now())
                .build();
        cartRepository.save(cart);

        auditRepository.save(BusinessAudit.builder()
                .sessionId(session.getId())
                .accountId(cashierId)
                .action("TABLE_SESSION_OPENED_BY_CASHIER")
                .afterState("OPEN")
                .createdAt(Instant.now())
                .build());

        realtimeEventPublisher.publishAfterCommit("/topic/cashier", "TABLE_SESSION_OPENED", session.getId().toString(), session.getId().toString(), "1", java.util.Map.of("tableId", table.getId(), "tableName", table.getName()));
        realtimeEventPublisher.publishAfterCommit("/topic/table-sessions/" + session.getId(), "TABLE_SESSION_OPENED", session.getId().toString(), session.getId().toString(), "1", java.util.Map.of("tableId", table.getId(), "tableName", table.getName()));

        return session;
    }

public void assignCounterOrderToTable(Long orderId, Long tableId, Long cashierId) {
        Order order = orderRepository.findByIdWithLock(orderId)
                .orElseThrow(() -> BusinessException.notFound(ErrorCode.ORDER_STATE_CONFLICT, "Không tìm thấy đơn hàng"));
        branchService.assertStaff(order, cashierId);
        if (order.getSource() != OrderSource.COUNTER) {
            throw BusinessException.badRequest(ErrorCode.ORDER_STATE_CONFLICT, "Chỉ được gắn đơn hàng tại quầy vào bàn");
        }
        if (order.getSession() != null) {
            throw BusinessException.badRequest(ErrorCode.ORDER_STATE_CONFLICT, "Đơn hàng đã được gắn vào phiên bàn khác");
        }
        // Mở phiên nếu bàn chưa có phiên, hoặc lấy phiên hiện tại
        var targetTable = tableRepository.findByIdWithLock(tableId).orElseThrow(() ->
                BusinessException.notFound(ErrorCode.TABLE_NOT_FOUND,"Không tìm thấy bàn"));
        var targetShop = branchService.tableBranch(targetTable);
        if (order.getShop() != null && !order.getShop().getId().equals(targetShop.getId()))
            throw BusinessException.forbidden(ErrorCode.ACCESS_DENIED,"Không được gắn đơn sang bàn khác cơ sở");
        TableSession session = tableSessionService.openByCashier(tableId, cashierId);
        order.setSession(session);
        orderRepository.save(order);
        auditRepository.save(BusinessAudit.builder()
                .sessionId(session.getId())
                .orderId(order.getId())
                .accountId(cashierId)
                .action("ORDER_ASSIGNED_TO_TABLE")
                .reason("Gắn đơn quầy vào bàn #" + tableId)
                .createdAt(Instant.now())
                .build());
        realtimeEventPublisher.publishAfterCommit("/topic/cashier", "ORDER_ASSIGNED_TO_TABLE", order.getId().toString(), session.getId().toString(), "1", Map.of("orderId", order.getId()));
        realtimeEventPublisher.publishAfterCommit("/topic/table-sessions/" + session.getId(), "ORDER_ASSIGNED_TO_TABLE", order.getId().toString(), session.getId().toString(), "1", Map.of("orderId", order.getId()));
    }

