public OrderDto.OrderWorkSummaryResponse getOrderWorkSummary() {
        List<Order> allOrders = orderRepository.findAll().stream().filter(this::staffCanRead).toList();
        long totalCount = allOrders.size();
        long confirmCount = 0;
        long cookingCount = 0;
        long completedCount = 0;
        long transferCount = 0;
        long cancelCount = 0;
        long refundCount = 0;
        Set<Long> pendingActionOrderIds = new HashSet<>();

        var allRefunds = refundRepository.findAll();
        Map<Long, vn.edu.ute.milktea.entity.cancellation.RefundRequest> refundByOrderId = allRefunds.stream()
                .collect(java.util.stream.Collectors.toMap(r -> r.getOrder().getId(), r -> r, (r1, r2) -> r1));

        for (Order o : allOrders) {
            boolean isStaffCreated = o.getAccount() != null && (o.getAccount().getRole() == Role.CASHIER || o.getAccount().getRole() == Role.ADMIN);
            if (o.getStatus() == OrderStatus.CHO_XAC_NHAN && !isStaffCreated) {
                confirmCount++;
                pendingActionOrderIds.add(o.getId());
            }

            if (o.getStatus() == OrderStatus.CHO_CHE_BIEN || o.getStatus() == OrderStatus.DANG_CHE_BIEN) {
                cookingCount++;
            }

            if (o.getStatus() == OrderStatus.HOAN_THANH) {
                completedCount++;
            }

            Invoice inv = invoiceRepository.findByOrderId(o.getId()).orElse(null);
            boolean isPaid = inv != null && paymentRepository.existsByInvoiceId(inv.getId());

            boolean hasPendingCancel = cancellationRepository.findFirstByOrderIdAndStatus(
                    o.getId(), CancellationStatus.CHO).isPresent();
            if (hasPendingCancel && o.getStatus() == OrderStatus.CHO_CHE_BIEN && isPaid) {
                cancelCount++;
                pendingActionOrderIds.add(o.getId());
            }

            if (inv != null && inv.getStatus() == InvoiceStatus.HIEU_LUC && !isPaid && o.getStatus() != OrderStatus.DA_HUY) {
                var latestNotice = paymentNoticeRepository.findFirstByInvoiceIdOrderByCreatedAtDescIdDesc(inv.getId());
                if (latestNotice.isPresent() && latestNotice.get().getMethod() == vn.edu.ute.milktea.entity.payment.PaymentMethod.BANK_TRANSFER) {
                    String ref = latestNotice.get().getReference();
                    if (ref != null && (ref.startsWith("NOTICE_") || ref.startsWith("TRANSFERRED_") || ref.startsWith("CUSTOMER_TRANSFERRED_"))) {
                        transferCount++;
                        pendingActionOrderIds.add(o.getId());
                    }
                }
            }

            if (o.getStatus() == OrderStatus.DA_HUY && isPaid) {
                var refReq = refundByOrderId.get(o.getId());
                if (refReq == null || refReq.getStatus() != vn.edu.ute.milktea.entity.cancellation.RefundStatus.DA_HOAN) {
                    refundCount++;
                    pendingActionOrderIds.add(o.getId());
                }
            }
        }

        return OrderDto.OrderWorkSummaryResponse.builder()
                .totalCount(totalCount)
                .confirmCount(confirmCount)
                .cookingCount(cookingCount)
                .completedCount(completedCount)
                .transferCount(transferCount)
                .cancelCount(cancelCount)
                .refundCount(refundCount)
                .pendingActionCount(pendingActionOrderIds.size())
                .build();
    }

public void decideRefund(Long refundId, boolean approved, String reason, Long adminId) {
        RefundRequest refund = refundRepository.findByIdWithLock(refundId)
                .orElseThrow(() -> BusinessException.notFound(ErrorCode.VALIDATION_FAILED, "Không tìm thấy yêu cầu hoàn tiền"));

        if (refund.getStatus() != RefundStatus.CHO_DUYET) {
            throw BusinessException.conflict(ErrorCode.ORDER_STATE_CONFLICT, "Yêu cầu hoàn tiền đã được xử lý trước đó");
        }

        Account admin = adminId != null ? accountRepository.findById(adminId).orElse(null) : null;
        refund.setApprovedBy(admin);
        refund.setApprovedAt(Instant.now());
        refund.setApprovalReason(reason);

        if (approved) {
            refund.setStatus(RefundStatus.DA_HOAN);
            refund.setRefundedBy(admin);
            refund.setRefundedAt(refund.getApprovedAt());
            refund.setRefundReference("ADMIN_BANK_REFUND_" + refundId);
            auditRepository.save(BusinessAudit.builder()
                    .orderId(refund.getOrder().getId())
                    .accountId(adminId)
                    .action("BANK_REFUND_APPROVED")
                    .reason(reason != null && !reason.isBlank() ? reason : "Admin xác nhận đã hoàn chuyển khoản")
                    .createdAt(Instant.now())
                    .build());
        } else {
            refund.setStatus(RefundStatus.TU_CHOI);
            auditRepository.save(BusinessAudit.builder()
                    .orderId(refund.getOrder().getId())
                    .accountId(adminId)
                    .action("BANK_REFUND_REJECTED")
                    .reason(reason)
                    .createdAt(Instant.now())
                    .build());
        }

        refundRepository.save(refund);
        publish(refund);
    }

public void updateSettings(SettingsDto.UpdateSettingsRequest request, Long adminId) {
        Account admin = adminId != null ? accountRepository.findById(adminId).orElse(null) : null;

        GlobalSettings settings = settingsRepository.findById(1)
                .orElseGet(() -> GlobalSettings.builder()
                        .id(1)
                        .build());

        settings.setShopName(request.getShopName());
        settings.setAddress(request.getAddress());
        settings.setBankName(request.getBankName());
        settings.setBankAccountNumber(request.getBankAccountNumber());
        settings.setBankAccountHolder(request.getBankAccountHolder());

        String type = request.getDiscountType();
        if (type == null || type.isBlank()) {
            type = "PERCENT";
        }
        type = type.trim().toUpperCase();
        if (!"PERCENT".equals(type) && !"FIXED_AMOUNT".equals(type)) {
            type = "PERCENT";
        }

        BigDecimal val = request.getDiscountValue();
        if (val == null) {
            val = request.getDiscountPercent() != null ? request.getDiscountPercent() : BigDecimal.ZERO;
        }

        if ("PERCENT".equals(type)) {
            if (val.compareTo(BigDecimal.ZERO) < 0 || val.compareTo(new BigDecimal("100")) > 0) {
                throw vn.edu.ute.milktea.common.BusinessException.badRequest(
                        vn.edu.ute.milktea.common.ErrorCode.VALIDATION_FAILED,
                        "Phần trăm giảm giá phải từ 0% đến 100%");
            }
            settings.setDiscountType("PERCENT");
            settings.setDiscountPercent(val);
            settings.setDiscountValue(val);
        } else {
            if (val.compareTo(BigDecimal.ZERO) < 0) {
                throw vn.edu.ute.milktea.common.BusinessException.badRequest(
                        vn.edu.ute.milktea.common.ErrorCode.VALIDATION_FAILED, "Số tiền giảm cố định không được âm");
            }
            settings.setDiscountType("FIXED_AMOUNT");
            settings.setDiscountValue(val);
            settings.setDiscountPercent(BigDecimal.ZERO);
        }

        settings.setModifiedBy(admin);
        settings.setModifiedAt(Instant.now());

        settingsRepository.save(settings);

        realtimeEventPublisher.publishAfterCommit("/topic/admin", "SETTINGS_CHANGED", "1", null, "1",
                java.util.Map.of("shopName", settings.getShopName()));
        realtimeEventPublisher.publishAfterCommit("/topic/cashier", "SETTINGS_CHANGED", "1", null, "1",
                java.util.Map.of("shopName", settings.getShopName()));
    }

public ReportDto.RevenueReportView getRevenueReport(LocalDate fromDate, LocalDate toDate) {
        if (fromDate == null) fromDate = LocalDate.now(VIETNAM_ZONE).minusDays(30);
        if (toDate == null) toDate = LocalDate.now(VIETNAM_ZONE);

        Instant startInstant = fromDate.atStartOfDay(VIETNAM_ZONE).toInstant();
        Instant endInstant = toDate.plusDays(1).atStartOfDay(VIETNAM_ZONE).toInstant();

        // 1. Thực thu (Payments completed trong khoảng)
        List<Payment> payments = paymentRepository.findByPaidAtBetween(startInstant, endInstant);
        BigDecimal received = payments.stream()
                .map(Payment::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);

        // 2. Thực hoàn (Refunds DA_HOAN trong khoảng)
        List<RefundRequest> refunds = refundRepository.findCompletedRefundsBetween(startInstant, endInstant);
        BigDecimal refunded = refunds.stream()
                .map(RefundRequest::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);

        // 3. Thu ròng = Thực thu - Thực hoàn
        BigDecimal netReceived = received.subtract(refunded);

        // 4. Doanh số đơn hoàn thành (completedOrderValue)
        var completedOrders = orderRepository.findByStatusInOrderByCreatedAtAsc(List.of(OrderStatus.HOAN_THANH));
        BigDecimal completedOrderValue = BigDecimal.ZERO;
        for (var ord : completedOrders) {
            if (ord.getCompletedAt() != null &&
                    !ord.getCompletedAt().isBefore(startInstant) &&
                    ord.getCompletedAt().isBefore(endInstant)) {
                Invoice inv = invoiceRepository.findByOrderId(ord.getId()).orElse(null);
                if (inv != null && inv.getStatus() == InvoiceStatus.HIEU_LUC) {
                    completedOrderValue = completedOrderValue.add(inv.getTotalAmount());
                }
            }
        }

        // 5. Dư nợ hiện tại (Tất cả hóa đơn HIEU_LUC chưa có payment)
        List<Invoice> allInvoices = invoiceRepository.findAll();
        BigDecimal currentOutstanding = BigDecimal.ZERO;
        for (Invoice inv : allInvoices) {
            if (inv.getStatus() == InvoiceStatus.HIEU_LUC) {
                if (!paymentRepository.existsByInvoiceId(inv.getId())) {
                    currentOutstanding = currentOutstanding.add(inv.getTotalAmount());
                }
            }
        }

        return ReportDto.RevenueReportView.builder()
                .fromDate(fromDate)
                .toDate(toDate)
                .currency("VND")
                .received(received)
                .refunded(refunded)
                .netReceived(netReceived)
                .completedOrderValue(completedOrderValue)
                .currentOutstanding(currentOutstanding)
                .build();
    }

public ReportDto.DashboardResponse getDashboard(
        LocalDate fromDate,
        LocalDate toDate) {

    LocalDate today = LocalDate.now(VIETNAM_ZONE);

    if (toDate == null) {
        toDate = today;
    }

    if (fromDate == null) {
        fromDate = toDate.minusDays(6);
    }

    if (fromDate.isAfter(toDate)) {
        throw new IllegalArgumentException(
                "Ngày bắt đầu không được lớn hơn ngày kết thúc"
        );
    }

    return ReportDto.DashboardResponse.builder()
            .fromDate(fromDate)
            .toDate(toDate)
