public OrderView assignShipper(CurrentActor a,Long orderId,AssignShipper input){
  var o=orders.lockId(orderId).orElseThrow(this::denied);scope(a,o.getShop().getId());version(o,input.version());
  if(o.getStatus()!=DeliveryOrder.Status.CONFIRMED)throw invalid("Chỉ phân công đơn đã xác nhận");
  var shipper=accounts.findById(input.accountId()).filter(x->x.getRole()==Role.SHIPPER&&Boolean.TRUE.equals(x.getActive())).orElseThrow(()->invalid("Shipper không hoạt động"));o.setShipper(shipper);orders.flush();return orderView(o);
 }

public OrderView transition(CurrentActor a,Long orderId,Transition input){
  var o=ownedOrder(a,orderId);version(o,input.version());
  boolean buyer=o.getAccount().getId().equals(id(a));
  boolean shipper=a.hasRole(Role.SHIPPER)&&o.getShipper()!=null&&o.getShipper().getId().equals(id(a));
  boolean seller=admin(a)||shops.findAccessible(id(a)).stream().anyMatch(s->s.getId().equals(o.getShop().getId())&&((a.hasRole(Role.VENDOR)&&s.getOwner().getId().equals(id(a)))||a.hasRole(Role.MANAGER)));
  var before=o.getStatus();var next=input.status();boolean allowed=false;
  if(before==next)return orderView(o);
  switch(next){
   case CONFIRMED -> allowed=seller&&before==DeliveryOrder.Status.NEW;
   case SHIPPING -> allowed=(shipper||admin(a))&&before==DeliveryOrder.Status.CONFIRMED&&(o.getPaymentMethod()==DeliveryOrder.Method.COD||o.isPaid());
   case DELIVERED -> allowed=(shipper||admin(a))&&before==DeliveryOrder.Status.SHIPPING;
   case DELIVERY_FAILED -> allowed=(shipper||admin(a))&&before==DeliveryOrder.Status.SHIPPING;
   case CANCELLED -> allowed=(buyer&&before==DeliveryOrder.Status.NEW)||(seller&&(before==DeliveryOrder.Status.NEW||before==DeliveryOrder.Status.CONFIRMED||before==DeliveryOrder.Status.DELIVERY_FAILED));
   case RETURN_REQUESTED -> allowed=buyer&&before==DeliveryOrder.Status.DELIVERED;
   case RETURNED -> allowed=seller&&before==DeliveryOrder.Status.RETURN_REQUESTED;
   case REFUNDED -> {
    allowed=admin(a)&&o.isPaid()&&(before==DeliveryOrder.Status.RETURNED||before==DeliveryOrder.Status.CANCELLED)&&o.getPaymentMethod()==DeliveryOrder.Method.COD;
    if(allowed&&(input.reference()==null||input.reference().isBlank()))throw invalid("Cần tham chiếu phiếu hoàn tiền thực tế");
   }
   default -> {}
  }
  if(!allowed)throw BusinessException.conflict(ErrorCode.ORDER_STATE_CONFLICT,"Không đủ quyền hoặc chuyển trạng thái không hợp lệ");
  if(next==DeliveryOrder.Status.CANCELLED||next==DeliveryOrder.Status.RETURNED){
   for(var line:o.getLines().stream().sorted(Comparator.comparing(l->l.getProduct().getId())).toList()){
    var p=products.findByIdWithLock(line.getProduct().getId()).orElseThrow(this::denied);p.setDeliveryStock(Math.addExact(p.getDeliveryStock(),line.getQuantity()));
   }
  }
  if(next==DeliveryOrder.Status.DELIVERED){o.setDeliveredAt(Instant.now());if(o.getPaymentMethod()==DeliveryOrder.Method.COD)o.setPaid(true);}
  if(next==DeliveryOrder.Status.DELIVERY_FAILED)o.setDeliveryFailed(true);
  if(next==DeliveryOrder.Status.REFUNDED)o.setRefundReference(input.reference().trim());
  o.setStatus(next);orders.flush();return orderView(o);
 }

public Map<String,String> ipn(Map<String,String> input){
  if(!configured())return reply("99","Gateway not configured");
  Map<String,String> fields=new TreeMap<>();input.forEach((k,v)->{if(k.startsWith("vnp_")&&!k.equals("vnp_SecureHash")&&!k.equals("vnp_SecureHashType"))fields.put(k,v);});
  String actual=Objects.toString(input.get("vnp_SecureHash"),"");
  if(!actual.matches("[0-9a-fA-F]{128}")||!MessageDigest.isEqual(sign(fields).getBytes(StandardCharsets.US_ASCII),actual.toLowerCase(Locale.ROOT).getBytes(StandardCharsets.US_ASCII)))return reply("97","Invalid signature");
  if(!tmnCode.equals(fields.get("vnp_TmnCode")))return reply("97","Invalid merchant");
  String ref=fields.get("vnp_TxnRef");if(ref==null||!ref.matches("[0-9]{1,18}"))return reply("01","Order not found");
  var optional=orders.lockId(Long.valueOf(ref));if(optional.isEmpty())return reply("01","Order not found");var o=optional.get();
  String amount=fields.get("vnp_Amount");
  if(amount==null||!amount.matches("[0-9]{1,20}")||!o.getTotalAmount().movePointRight(2).toBigIntegerExact().equals(new java.math.BigInteger(amount)))return reply("04","Invalid amount");
  if(o.getPaymentMethod()!=DeliveryOrder.Method.VNPAY)return reply("99","Invalid payment method");
  if(o.isPaid())return reply("02","Order already confirmed");
  if(!"00".equals(fields.get("vnp_ResponseCode"))||!"00".equals(fields.get("vnp_TransactionStatus")))return reply("00","Unsuccessful payment acknowledged");
  String transaction=fields.get("vnp_TransactionNo");if(transaction==null||!transaction.matches("[0-9]{1,15}")||orders.existsByGatewayReference(transaction))return reply("99","Invalid transaction reference");
  // A verified late payment is still money received, even if the user cancelled.
  // Keep order status unchanged; expose paid cancelled orders for manual gateway refund.
  o.setPaid(true);o.setGatewayReference(transaction);orders.flush();return reply("00","Confirm Success");
 }
